"""Synthetic, schema-conforming suite reduction tables.

The figure layer reads the columns defined by
:mod:`empirical_testing.experiments.schema`. These fixtures test that contract
using tables with the expected columns and deliberately invented values.

**These numbers are not results.**  Every value here is generated by the
deterministic toy model below; nothing in this module reads a run, and nothing
it produces may be reported.  It exists so that the figure code can be
exercised end to end -- including the parts that only matter when a table has
the shared NLHF benchmark, the active overlay at two betas, and per-group rows.

The toy model
-------------

Worst-group distortion is built as ``base(method) + beta_effect(beta)`` (or
``+ tau_effect(tau)``) plus a small deterministic per-cell jitter, with

* ``multigroup`` best, then ``pooled``, then ``pooled_nlhf``, then ``uniform``
  flat and worst -- the ordering the study reports, so a figure drawn from
  these tables looks like the figure drawn from real ones;
* active GLHF slightly better than passive at ``beta = 4`` and ``inf``;
* a shallow U in tau, minimized near the middle of the grid.

The cell inventory is taken from :mod:`empirical_testing.experiments.suite`
rather than re-spelled, so a fixture cannot describe a grid the suite does not
define.
"""

from __future__ import annotations

#: Stamped into every table this module builds.  The marker travels *in the
#: data*, so anything derived from these tables -- a figure, a plotted CSV --
#: can identify itself as synthetic without the caller having to remember to
#: say so.  :func:`figures.write_all_figures` refuses to write into a real
#: ``figures/coffee`` or ``figures/persona`` directory when it sees this, and
#: watermarks what it draws.
SYNTHETIC_MARKER_COLUMN = "synthetic_fixture"

import math
from typing import Any, Mapping

import pandas as pd

from empirical_testing.experiments import schema
from empirical_testing.experiments.suite import (
    DISPLAY_NAMES,
    EVALUATION_TAU,
    NLHF_BASELINE,
    TRAINING_PROTOCOL,
    Condition,
    beta_condition_cells,
    tau_condition_cells,
)

#: Groups the synthetic per-group tables carry.
GROUPS: tuple[str, ...] = (
    "age:45+", "gender:female", "expertise:1-3",
    "spend:$40-$60", "wfh:in-person", "universal",
)

_METHOD_BASE: Mapping[str, float] = {
    "multigroup": 1.06, "pooled": 1.14, "pooled_nlhf": 1.21, "uniform": 1.42,
}
_N_SPLITS = 100
_N_SEEDS = 50

_PROVENANCE: Mapping[str, Any] = {
    "suite_id": "coffee-comparison-suite-v10",
    "protocol_id": "coffee-protocol-beta-v10",
    "implementation_id": "synthetic-fixture",
    "config_sha256": "0" * 64,
    "source_design_id": "coffee-repeated-cv-v4-10x10",
    "nlhf_baseline": NLHF_BASELINE,
    "schema_version": schema.SCHEMA_VERSION,
}


def _beta_number(text: str) -> float:
    return math.inf if text == "inf" else float(text)


def _jitter(*parts: Any) -> float:
    """A small deterministic wiggle, so curves are not perfectly smooth."""

    seed = abs(hash("|".join(str(p) for p in parts))) % 1000
    return (seed / 1000.0 - 0.5) * 0.012


def _beta_effect(beta: float) -> float:
    """Distortion falls as the label model sharpens, flattening at infinity."""

    if math.isinf(beta):
        return 0.0
    return 0.18 / (1.0 + beta)


def _tau_effect(tau: float) -> float:
    """A shallow U in the learner radius, minimized near tau = 0.35."""

    return 0.30 * (tau - 0.35) ** 2 + 0.02


def _level(cell: Condition) -> float:
    if cell.method == "uniform":
        return _METHOD_BASE["uniform"] + _jitter(cell.condition, cell.method)
    base = _METHOD_BASE[cell.method]
    if cell.condition == "beta":
        value = base + _beta_effect(cell.beta)
        if cell.protocol == "active":
            value -= 0.035
    else:
        value = base + _tau_effect(cell.learner_tau)
    return value + _jitter(cell.label)


def _se(cell: Condition) -> float:
    return 0.021 + 0.004 * abs(_jitter(cell.label, "se")) * 40


def _cell_columns(cell: Condition) -> dict[str, Any]:
    return {
        "condition": cell.condition,
        "protocol": cell.protocol,
        "beta": "inf" if math.isinf(cell.beta) else f"{cell.beta:g}",
        "learner_tau": cell.learner_tau,
        "evaluation_tau": EVALUATION_TAU,
    }


def _method_columns(cell: Condition) -> dict[str, Any]:
    return {
        "method": cell.method,
        "display_name": DISPLAY_NAMES[cell.method],
        "training_protocol": TRAINING_PROTOCOL[cell.method],
        "provenance": cell.provenance,
        "shared_with": cell.shared_with or "",
        "displayed_beside_protocol": cell.displayed_beside or "",
    }


def _inference(estimate: float, se: float, *, key: str, family: str) -> dict[str, Any]:
    half = 1.984 * se
    t = estimate / se if se else 0.0
    p = max(min(2.0 * math.exp(-0.5 * abs(t)), 1.0), 1e-6)
    return {
        "estimate": estimate,
        "corrected_se": se,
        "df": _N_SPLITS - 1,
        "ci_low": estimate - half,
        "ci_high": estimate + half,
        "t": t,
        "p_value": p,
        "p_holm": min(p * 3.0, 1.0),
        "holm_family": schema.HOLM_FAMILIES[family],
        "n_splits": _N_SPLITS,
        "n_seeds": _N_SEEDS,
        "variance_factor": 1.0 / _N_SPLITS + 1.0 / 9.0,
        "mean_test_train_ratio": 1.0 / 9.0,
        **{"_key": key},
    }


def _drop_key(row: dict[str, Any]) -> dict[str, Any]:
    row.pop("_key", None)
    return row


# --------------------------------------------------------------- the tables


def method_levels() -> pd.DataFrame:
    rows = []
    for cell in beta_condition_cells() + tau_condition_cells():
        estimate = _level(cell)
        rows.append({
            **_cell_columns(cell), **_method_columns(cell),
            "worst_group_distortion": estimate,
            "worst_group_se": _se(cell),
            "welfare": 1.0 / estimate,
            "welfare_optimum": 1.0,
            **_PROVENANCE,
        })
    return pd.DataFrame(rows, columns=list(schema.TABLES["method_levels"]))


def method_group_levels() -> pd.DataFrame:
    rows = []
    for cell in beta_condition_cells() + tau_condition_cells():
        worst = _level(cell)
        for position, group in enumerate(GROUPS):
            # Groups sit below the worst-group maximum by a group-specific
            # amount; the worst group itself sits at the maximum.
            offset = 0.0 if position == 0 else 0.03 * position + _jitter(cell.label, group)
            rows.append({
                **_cell_columns(cell), **_method_columns(cell),
                "group": group,
                "distortion": worst - offset,
                "distortion_se": _se(cell) * 1.1,
                "n_test_group": 340 - 11 * position,
                **_PROVENANCE,
            })
    return pd.DataFrame(rows, columns=list(schema.TABLES["method_group_levels"]))


def _contrast_rows(per_group: bool) -> list[dict[str, Any]]:
    levels = {}
    for cell in beta_condition_cells() + tau_condition_cells():
        levels[(cell.condition, cell.protocol, cell.displayed_beside or "",
                _cell_columns(cell)["beta"], cell.learner_tau, cell.method)] = cell
    rows: list[dict[str, Any]] = []
    seen: set[tuple[Any, ...]] = set()
    for cell in beta_condition_cells() + tau_condition_cells():
        if cell.method != "multigroup":
            continue
        base = _cell_columns(cell)
        for minuend, subtrahend in schema.PAIRWISE_CONTRASTS:
            # Every pair of PAIRWISE_CONTRASTS is carried, not only the
            # "minus multigroup GLHF" family the gap figures draw, so the table
            # is the whole family Holm ranges over.
            key = (cell.condition, cell.protocol, base["beta"], cell.learner_tau,
                   minuend, subtrahend)
            if key in seen:
                continue
            seen.add(key)
            minuend_cell = _find(levels, cell, minuend)
            subtrahend_cell = _find(levels, cell, subtrahend)
            if minuend_cell is None or subtrahend_cell is None:
                continue
            estimate = _level(minuend_cell) - _level(subtrahend_cell)
            se = 0.5 * (_se(minuend_cell) + _se(subtrahend_cell))
            groups = GROUPS if per_group else (None,)
            for position, group in enumerate(groups):
                value = estimate if group is None else estimate * (1.0 + 0.08 * position)
                payload = {
                    **base,
                    "contrast": f"{minuend}_minus_{subtrahend}",
                    "minuend": minuend, "subtrahend": subtrahend,
                    "minuend_training_protocol": TRAINING_PROTOCOL[minuend],
                    "subtrahend_training_protocol": TRAINING_PROTOCOL[subtrahend],
                    "positive_favors": subtrahend,
                    **_drop_key(_inference(
                        value, se, key="", family="per_group" if per_group else "worst_group")),
                    **_PROVENANCE,
                }
                if group is not None:
                    payload["group"] = group
                rows.append(payload)
    return rows


def _find(levels, cell: Condition, method: str) -> Condition | None:
    """The cell of ``method`` that is displayed where ``cell`` is displayed."""

    beta = _cell_columns(cell)["beta"]
    position = cell.displayed_beside or cell.protocol
    for (condition, protocol, displayed, b, tau, m), found in levels.items():
        if condition != cell.condition or m != method:
            continue
        if b != beta or tau != cell.learner_tau:
            continue
        if (displayed or protocol) == position:
            return found
    return None


def method_contrasts() -> pd.DataFrame:
    return pd.DataFrame(_contrast_rows(per_group=False),
                        columns=list(schema.TABLES["method_contrasts"]))


def method_group_contrasts() -> pd.DataFrame:
    return pd.DataFrame(_contrast_rows(per_group=True),
                        columns=list(schema.TABLES["method_group_contrasts"]))


def protocol_contrasts() -> pd.DataFrame:
    """Active minus passive GLHF, at beta 4 and infinity only."""

    rows = []
    by_key = {}
    for cell in beta_condition_cells():
        by_key[(cell.protocol, _cell_columns(cell)["beta"], cell.method)] = cell
    for beta in ("4", "inf"):
        for method in ("multigroup", "pooled"):
            active = by_key.get(("active", beta, method))
            passive = by_key.get(("passive", beta, method))
            if active is None or passive is None:
                continue
            estimate = _level(active) - _level(passive)
            se = 0.5 * (_se(active) + _se(passive))
            rows.append({
                **_cell_columns(active),
                "method": method,
                "display_name": DISPLAY_NAMES[method],
                "contrast": "active_minus_passive",
                "positive_favors": "passive",
                **_drop_key(_inference(estimate, se, key="", family="worst_group")),
                **_PROVENANCE,
            })
    return pd.DataFrame(rows, columns=list(schema.TABLES["protocol_contrasts"]))


def synthetic_tables() -> dict[str, pd.DataFrame]:
    """Every table the figure layer reads, as schema-conforming DataFrames."""

    tables = {
        "method_levels": method_levels(),
        "method_group_levels": method_group_levels(),
        "method_contrasts": method_contrasts(),
        "method_group_contrasts": method_group_contrasts(),
        "protocol_contrasts": protocol_contrasts(),
    }
    # The marker rides in the data, not in a convention the caller has to
    # remember.  A real reduction never sets it.
    for frame in tables.values():
        frame[SYNTHETIC_MARKER_COLUMN] = True
    return tables


def write_synthetic_tables(directory) -> dict[str, Any]:
    """Write the synthetic tables as CSVs, the way a reduction would."""

    from pathlib import Path

    out = Path(directory)
    out.mkdir(parents=True, exist_ok=True)
    written = {}
    for name, frame in synthetic_tables().items():
        path = out / f"{name}.csv"
        frame.to_csv(path, index=False)
        written[name] = path
    return written
